export const SCHEMA_SQL = "-- Khan Baba platform schema (PostgreSQL / Supabase).\n--\n-- Applied automatically on the first query of every process (see lib/db/index.ts):\n-- every statement is idempotent, so this file doubles as the migration script.\n-- Types: identity integers for keys, timestamptz for instants, date for calendar\n-- days, boolean for flags, double precision for quantities and integer cents for\n-- money (never floats — the money math stays in whole cents).\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS staff (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  role TEXT NOT NULL CHECK (role IN ('admin','manager','counter','kitchen','delivery')),\n  password_hash TEXT NOT NULL,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS categories (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  slug TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  description TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\nCREATE TABLE IF NOT EXISTS menu_items (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  slug TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  tagline TEXT,\n  description TEXT,\n  category_id INTEGER REFERENCES categories(id),\n  image TEXT,\n  gallery TEXT,                       -- JSON array of image paths\n  youtube_id TEXT,                    -- plays inline via youtube-nocookie\n  ingredients TEXT,                   -- comma separated, customer facing\n  allergens TEXT,                     -- comma separated\n  spice_levels TEXT NOT NULL DEFAULT 'blend,mild,hot,extra_hot',\n  prep_minutes INTEGER NOT NULL DEFAULT 15,\n  is_veg BOOLEAN NOT NULL DEFAULT FALSE,\n  is_available BOOLEAN NOT NULL DEFAULT TRUE,\n  is_featured BOOLEAN NOT NULL DEFAULT FALSE,\n  is_new BOOLEAN NOT NULL DEFAULT FALSE,\n  published BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS item_variants (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  item_id INTEGER NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,\n  label TEXT NOT NULL,\n  size_ml INTEGER,\n  price_cents INTEGER NOT NULL,\n  is_default BOOLEAN NOT NULL DEFAULT FALSE,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_variants_item ON item_variants(item_id);\n\nCREATE TABLE IF NOT EXISTS reviews (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  item_id INTEGER NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,\n  order_code TEXT,\n  customer_name TEXT NOT NULL,\n  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),\n  comment TEXT,\n  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','hidden')),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_reviews_item ON reviews(item_id, status);\n\n-- Manufacturing / costing ---------------------------------------------------\nCREATE TABLE IF NOT EXISTS materials (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  sku TEXT UNIQUE,\n  unit TEXT NOT NULL DEFAULT 'kg',\n  pack_qty DOUBLE PRECISION NOT NULL DEFAULT 1,   -- how much one purchase pack contains (in `unit`)\n  pack_cost_cents INTEGER NOT NULL DEFAULT 0,\n  stock_qty DOUBLE PRECISION NOT NULL DEFAULT 0,  -- current stock in `unit`\n  reorder_level DOUBLE PRECISION NOT NULL DEFAULT 0,\n  supplier TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS recipes (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  output_kind TEXT NOT NULL DEFAULT 'batch' CHECK (output_kind IN ('menu_item','batch')),\n  menu_item_id INTEGER REFERENCES menu_items(id),\n  output_qty DOUBLE PRECISION NOT NULL DEFAULT 1,\n  output_unit TEXT NOT NULL DEFAULT 'portion',\n  prep_minutes INTEGER NOT NULL DEFAULT 30,\n  notes TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS recipe_lines (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  recipe_id INTEGER NOT NULL REFERENCES recipes(id) ON DELETE CASCADE,\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  qty DOUBLE PRECISION NOT NULL,\n  unit TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_recipe_lines ON recipe_lines(recipe_id);\n\nCREATE TABLE IF NOT EXISTS production_batches (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  ref TEXT NOT NULL UNIQUE,\n  recipe_id INTEGER NOT NULL REFERENCES recipes(id),\n  planned_qty DOUBLE PRECISION NOT NULL,\n  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress','completed','cancelled')),\n  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  completed_at TIMESTAMPTZ,\n  created_by TEXT,\n  total_cost_cents INTEGER NOT NULL DEFAULT 0,\n  notes TEXT\n);\n\nCREATE TABLE IF NOT EXISTS cost_postings (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  batch_id INTEGER NOT NULL REFERENCES production_batches(id) ON DELETE CASCADE,\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  material_name TEXT NOT NULL,\n  qty DOUBLE PRECISION NOT NULL,\n  unit TEXT,\n  unit_cost_cents INTEGER NOT NULL,\n  amount_cents INTEGER NOT NULL,\n  posted_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_cost_postings_batch ON cost_postings(batch_id);\n\n-- Pricing -------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS pricing_rules (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  label TEXT NOT NULL,\n  kind TEXT NOT NULL CHECK (kind IN ('weekend','public_holiday','priority','peak')),\n  calc TEXT NOT NULL CHECK (calc IN ('percent','flat')),\n  value DOUBLE PRECISION NOT NULL,\n  applies_to TEXT NOT NULL DEFAULT 'all',      -- all | delivery,pickup | delivery | pickup | dine_in | table\n  days TEXT,                                   -- CSV 0=Sun..6=Sat, null = every day\n  start_time TEXT,                             -- HH:MM (Sydney)\n  end_time TEXT,\n  min_subtotal_cents INTEGER NOT NULL DEFAULT 0,\n  description TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS holidays (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  date DATE NOT NULL UNIQUE,                   -- read back as text YYYY-MM-DD\n  name TEXT NOT NULL,\n  surcharge_percent DOUBLE PRECISION,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\nCREATE TABLE IF NOT EXISTS dining_tables (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  zone TEXT,\n  seats INTEGER NOT NULL DEFAULT 4,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\n-- Customers -----------------------------------------------------------------\n-- An account is optional: browsing, table QR ordering and the tracking link all\n-- work signed out. These rows are what turn a one-off order into history —\n-- \"my orders\", saved delivery details, and a counter lookup that does not\n-- depend on the customer remembering an order code. Guests are rows with\n-- guest = TRUE and no password; they are upgraded in place at sign-up.\nCREATE TABLE IF NOT EXISTS customers (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,                 -- stored lowercased\n  phone TEXT,\n  password_hash TEXT,                         -- null until a guest registers\n  address TEXT,\n  suburb TEXT,\n  postcode TEXT,\n  marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE,\n  guest BOOLEAN NOT NULL DEFAULT FALSE,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  last_order_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_customers_email ON customers(lower(email));\n\nCREATE TABLE IF NOT EXISTS customer_activity (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL,                          -- signup | signin | order | orders_claimed | profile_updated\n  detail TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_customer_activity ON customer_activity(customer_id, created_at DESC);\n\n-- Orders --------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS orders (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  customer_id INTEGER REFERENCES customers(id),\n  tracking_token TEXT UNIQUE,                 -- the sharable /t/<token> link\n  channel TEXT NOT NULL CHECK (channel IN ('delivery','pickup','dine_in','table')),\n  table_id INTEGER REFERENCES dining_tables(id),\n  customer_name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  address TEXT,\n  suburb TEXT,\n  postcode TEXT,\n  notes TEXT,\n  subtotal_cents INTEGER NOT NULL DEFAULT 0,\n  surcharge_cents INTEGER NOT NULL DEFAULT 0,\n  surcharge_detail TEXT,\n  priority BOOLEAN NOT NULL DEFAULT FALSE,\n  priority_fee_cents INTEGER NOT NULL DEFAULT 0,\n  delivery_fee_cents INTEGER NOT NULL DEFAULT 0,\n  delivery_cost_cents INTEGER NOT NULL DEFAULT 0,\n  total_cents INTEGER NOT NULL DEFAULT 0,\n  payment_method TEXT NOT NULL CHECK (payment_method IN ('online','counter')),\n  payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','pending','paid','refunded','failed')),\n  payment_ref TEXT,\n  status TEXT NOT NULL DEFAULT 'pending_confirm' CHECK (status IN ('pending_confirm','confirmed','preparing','ready','out_for_delivery','awaiting_collection','completed','cancelled')),\n  progress INTEGER NOT NULL DEFAULT 5,\n  promised_at TIMESTAMPTZ,\n  confirmed_at TIMESTAMPTZ,\n  kitchen_started_at TIMESTAMPTZ,\n  ready_at TIMESTAMPTZ,\n  dispatched_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ,\n  cancelled_reason TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n-- Upgrades for databases created by an earlier release. CREATE TABLE IF NOT\n-- EXISTS skips a table that is already there, so a column added later never\n-- reaches an existing database on its own. Every column added to an existing\n-- table after its first release must also be listed here, above any index that\n-- uses it. ADD COLUMN IF NOT EXISTS is a no-op once the column exists.\nALTER TABLE orders ADD COLUMN IF NOT EXISTS customer_id INTEGER REFERENCES customers(id);\nALTER TABLE orders ADD COLUMN IF NOT EXISTS tracking_token TEXT UNIQUE;\n\nCREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_orders_channel ON orders(channel, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS order_items (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  item_id INTEGER,\n  variant_id INTEGER,\n  name TEXT NOT NULL,\n  variant_label TEXT,\n  size_ml INTEGER,\n  spice_level TEXT,\n  qty INTEGER NOT NULL DEFAULT 1,\n  unit_price_cents INTEGER NOT NULL,\n  line_total_cents INTEGER NOT NULL,\n  notes TEXT,\n  prep_state TEXT NOT NULL DEFAULT 'queued' CHECK (prep_state IN ('queued','preparing','ready'))\n);\nCREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);\n\nCREATE TABLE IF NOT EXISTS order_events (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  type TEXT NOT NULL,\n  message TEXT NOT NULL,\n  actor TEXT,\n  progress INTEGER,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_order_events ON order_events(order_id, created_at);\n\n-- One-time links that let a guest prove they own an order and attach it to an\n-- account. Only the SHA-256 of the token is stored, so a database leak cannot be\n-- replayed as anyone's tracking link, and used_at makes each link single-use.\nCREATE TABLE IF NOT EXISTS order_claims (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  token_hash TEXT NOT NULL UNIQUE,\n  email TEXT NOT NULL,\n  used_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_order_claims_order ON order_claims(order_id);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  provider TEXT NOT NULL,\n  intent_id TEXT,\n  amount_cents INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  method TEXT,\n  last4 TEXT,\n  raw TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  paid_at TIMESTAMPTZ\n);\n\n-- Delivery ------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS delivery_jobs (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  provider TEXT NOT NULL,\n  provider_quote_id TEXT,\n  provider_delivery_id TEXT,\n  cost_cents INTEGER NOT NULL DEFAULT 0,\n  customer_fee_cents INTEGER NOT NULL DEFAULT 0,\n  markup_cents INTEGER NOT NULL DEFAULT 0,\n  status TEXT NOT NULL DEFAULT 'quoted' CHECK (status IN ('quoted','requested','accepted','pickup','dropoff','delivered','cancelled','failed')),\n  courier_name TEXT,\n  courier_phone TEXT,\n  tracking_url TEXT,\n  eta_minutes INTEGER,\n  quote_json TEXT,\n  external_status TEXT,\n  triggered_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  dispatched_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_delivery_jobs_order ON delivery_jobs(order_id);\n\n-- What's new / release notes ------------------------------------------------\nCREATE TABLE IF NOT EXISTS whats_new (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  title TEXT NOT NULL,\n  summary TEXT NOT NULL,\n  body TEXT,\n  category TEXT NOT NULL DEFAULT 'feature' CHECK (category IN ('feature','improvement','fix','portal','ops')),\n  version TEXT,\n  pr_number INTEGER,\n  pr_url TEXT,\n  pinned BOOLEAN NOT NULL DEFAULT FALSE,\n  published_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- ===========================================================================\n-- v2 · delivery partners, driver network, promotions, returns/community,\n--       Square POS bridge and richer payments.\n--\n-- Everything below is additive. The tables are independent of the core order\n-- lifecycle (the POS bridge in particular is deliberately detached), so a\n-- deployment that never enables them behaves exactly as it did before.\n-- ===========================================================================\n\n-- Coordinates are stored with every delivery address (and the customer's saved\n-- address) so quotes, driver assignment, live tracking and ATO kilometre logs\n-- all work from the same pair. NULL simply means \"not geocoded yet\".\nALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_lat DOUBLE PRECISION;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_lng DOUBLE PRECISION;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS discount_cents INTEGER NOT NULL DEFAULT 0;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS promotion_code TEXT;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_option TEXT;\nALTER TABLE customers ADD COLUMN IF NOT EXISTS address_lat DOUBLE PRECISION;\nALTER TABLE customers ADD COLUMN IF NOT EXISTS address_lng DOUBLE PRECISION;\nALTER TABLE item_variants ADD COLUMN IF NOT EXISTS square_variation_id TEXT;\n\n-- Driver partners -----------------------------------------------------------\n-- Onboarding is a verification workflow: an application creates a `pending`\n-- driver plus one document row per required check. Nothing is dispatchable\n-- until every document is `verified` and the driver is `approved`.\nCREATE TABLE IF NOT EXISTS drivers (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  first_name TEXT NOT NULL,\n  last_name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  phone TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK (status IN ('pending','under_review','approved','suspended','rejected')),\n  vehicle_type TEXT NOT NULL DEFAULT 'car',    -- car | motorbike | bicycle | van\n  vehicle_rego TEXT,\n  vehicle_make TEXT,\n  licence_number TEXT,                        -- reference only; never a full scan\n  licence_state TEXT,\n  licence_expiry DATE,\n  insurance_provider TEXT,\n  insurance_expiry DATE,\n  abn TEXT,\n  right_to_work_country TEXT,\n  police_check_ref TEXT,\n  pay_id TEXT,\n  address TEXT,\n  suburb TEXT,\n  postcode TEXT,\n  base_lat DOUBLE PRECISION,\n  base_lng DOUBLE PRECISION,\n  commission_percent DOUBLE PRECISION NOT NULL DEFAULT 15,\n  per_delivery_fee_cents INTEGER NOT NULL DEFAULT 300,\n  max_radius_km DOUBLE PRECISION NOT NULL DEFAULT 15,\n  current_lat DOUBLE PRECISION,\n  current_lng DOUBLE PRECISION,\n  last_seen_at TIMESTAMPTZ,\n  terms_accepted_at TIMESTAMPTZ,\n  privacy_accepted_at TIMESTAMPTZ,\n  approved_at TIMESTAMPTZ,\n  approved_by TEXT,\n  rejection_reason TEXT,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_drivers_status ON drivers(status, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS driver_documents (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL,                          -- photo_id | licence | insurance | police_check | right_to_work | abn | bank | vehicle_photo\n  reference TEXT,                              -- document number / licence ref\n  file_ref TEXT,                               -- optional uploaded file path or URL\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK (status IN ('pending','submitted','verified','rejected')),\n  expires_on DATE,\n  verified_by TEXT,\n  verified_at TIMESTAMPTZ,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (driver_id, kind)\n);\nCREATE INDEX IF NOT EXISTS idx_driver_documents ON driver_documents(driver_id, status);\n\nCREATE TABLE IF NOT EXISTS driver_verification_events (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,\n  action TEXT NOT NULL,\n  detail TEXT,\n  actor TEXT NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_driver_events ON driver_verification_events(driver_id, created_at DESC);\n\n-- Commission ledger: money is only posted when a delivery actually completes.\nCREATE TABLE IF NOT EXISTS driver_ledger (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,\n  job_id INTEGER,\n  order_id INTEGER,\n  kind TEXT NOT NULL CHECK (kind IN ('delivery_fee','commission','bonus','adjustment','payout')),\n  amount_cents INTEGER NOT NULL,\n  description TEXT,\n  settled_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_driver_ledger ON driver_ledger(driver_id, created_at DESC);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_driver_ledger_unique_job\n  ON driver_ledger(job_id, kind, driver_id) WHERE job_id IS NOT NULL;\n\nCREATE TABLE IF NOT EXISTS driver_location_pings (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,\n  order_id INTEGER,\n  job_id INTEGER,\n  lat DOUBLE PRECISION NOT NULL,\n  lng DOUBLE PRECISION NOT NULL,\n  accuracy_m DOUBLE PRECISION,\n  heading DOUBLE PRECISION,\n  speed_kmh DOUBLE PRECISION,\n  source TEXT NOT NULL DEFAULT 'driver_app',\n  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_driver_pings ON driver_location_pings(driver_id, order_id, recorded_at DESC);\n\n-- ATO-ready kilometre log. One row per delivered job; the cents-per-km rate is\n-- captured at the time of the trip so a past financial year never changes when\n-- the ATO publishes a new determination.\nCREATE TABLE IF NOT EXISTS driver_trips (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,\n  job_id INTEGER,\n  order_id INTEGER,\n  order_code TEXT,\n  start_lat DOUBLE PRECISION,\n  start_lng DOUBLE PRECISION,\n  end_lat DOUBLE PRECISION,\n  end_lng DOUBLE PRECISION,\n  distance_km DOUBLE PRECISION NOT NULL DEFAULT 0,\n  purpose TEXT NOT NULL DEFAULT 'Delivering customer orders',\n  method TEXT NOT NULL DEFAULT 'cents_per_km',  -- cents_per_km | logbook\n  source TEXT NOT NULL DEFAULT 'estimated',     -- gps | estimated | manual\n  financial_year TEXT NOT NULL,\n  rate_cents_per_km INTEGER NOT NULL DEFAULT 0,\n  claim_cents INTEGER NOT NULL DEFAULT 0,\n  started_at TIMESTAMPTZ,\n  ended_at TIMESTAMPTZ,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (job_id, driver_id)\n);\nCREATE INDEX IF NOT EXISTS idx_driver_trips_report ON driver_trips(driver_id, financial_year, ended_at);\n\nALTER TABLE delivery_jobs ADD COLUMN IF NOT EXISTS driver_id INTEGER REFERENCES drivers(id);\nALTER TABLE delivery_jobs ADD COLUMN IF NOT EXISTS driver_fee_cents INTEGER NOT NULL DEFAULT 0;\nALTER TABLE delivery_jobs ADD COLUMN IF NOT EXISTS driver_settled_at TIMESTAMPTZ;\nALTER TABLE delivery_jobs ADD COLUMN IF NOT EXISTS distance_km DOUBLE PRECISION;\nCREATE INDEX IF NOT EXISTS idx_delivery_jobs_driver ON delivery_jobs(driver_id, created_at DESC);\n\n-- Promotions (customers + driver partners) ----------------------------------\nCREATE TABLE IF NOT EXISTS promotions (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  description TEXT,\n  audience TEXT NOT NULL DEFAULT 'customer'\n    CHECK (audience IN ('customer','driver','both')),\n  kind TEXT NOT NULL DEFAULT 'percent'\n    CHECK (kind IN ('percent','flat','free_delivery','driver_bonus','driver_commission')),\n  value DOUBLE PRECISION NOT NULL DEFAULT 0,\n  max_discount_cents INTEGER NOT NULL DEFAULT 0,\n  min_subtotal_cents INTEGER NOT NULL DEFAULT 0,\n  channels TEXT,                               -- CSV of channels, NULL = all\n  driver_id INTEGER REFERENCES drivers(id),\n  starts_at TIMESTAMPTZ,\n  ends_at TIMESTAMPTZ,\n  usage_limit INTEGER NOT NULL DEFAULT 0,      -- 0 = unlimited\n  per_customer_limit INTEGER NOT NULL DEFAULT 0,\n  usage_count INTEGER NOT NULL DEFAULT 0,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_promotions_active ON promotions(active, audience);\n\nCREATE TABLE IF NOT EXISTS promotion_redemptions (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  promotion_id INTEGER NOT NULL REFERENCES promotions(id) ON DELETE CASCADE,\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  job_id INTEGER,\n  customer_id INTEGER,\n  driver_id INTEGER,\n  discount_cents INTEGER NOT NULL DEFAULT 0,\n  reward_cents INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (promotion_id, order_id)\n);\n\n-- Returns → community redistribution ---------------------------------------\nCREATE TABLE IF NOT EXISTS return_requests (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  code TEXT NOT NULL UNIQUE,\n  reason TEXT NOT NULL,\n  resolution TEXT NOT NULL DEFAULT 'community'\n    CHECK (resolution IN ('refund','replacement','community','waste')),\n  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved','cancelled')),\n  notes TEXT,\n  requested_by TEXT,\n  resolved_by TEXT,\n  resolved_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_returns_order ON return_requests(order_id, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS community_offers (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  return_id INTEGER REFERENCES return_requests(id) ON DELETE SET NULL,\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  token TEXT NOT NULL UNIQUE,\n  pickup_code TEXT NOT NULL UNIQUE,\n  title TEXT NOT NULL,\n  description TEXT,\n  contents TEXT,                               -- JSON array of {name, qty}\n  channel TEXT NOT NULL DEFAULT 'click_and_collect',\n  status TEXT NOT NULL DEFAULT 'draft'\n    CHECK (status IN ('draft','posted','claimed','expired','cancelled')),\n  claim_keyword TEXT NOT NULL DEFAULT 'MINE',\n  auto_reply_text TEXT,\n  facebook_post_id TEXT,\n  facebook_post_url TEXT,\n  facebook_mode TEXT NOT NULL DEFAULT 'sandbox',\n  posted_at TIMESTAMPTZ,\n  posted_by TEXT,\n  comments_closed BOOLEAN NOT NULL DEFAULT FALSE,\n  comments_moderated BOOLEAN NOT NULL DEFAULT FALSE,\n  auto_reply_posted_at TIMESTAMPTZ,\n  claimed_by TEXT,\n  claimed_at TIMESTAMPTZ,\n  claim_comment_id TEXT,\n  claim_source TEXT,                           -- facebook | portal\n  claim_order_code TEXT,                       -- zero-cost click & collect ticket\n  pickup_deadline TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_community_offers_status ON community_offers(status, posted_at DESC);\n\nCREATE TABLE IF NOT EXISTS community_offer_events (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  offer_id INTEGER NOT NULL REFERENCES community_offers(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL,\n  detail TEXT,\n  actor TEXT NOT NULL DEFAULT 'system',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Square POS bridge (deliberately detached) ---------------------------------\n-- The main platform never reads these tables to run an order. They are the\n-- synchronisation boundary: outbound pushes, inbound transactions and webhook\n-- receipts all land here, so the whole module can be removed without touching\n-- the order state machine.\nCREATE TABLE IF NOT EXISTS square_sync_records (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  direction TEXT NOT NULL CHECK (direction IN ('outbound','inbound','webhook','test')),\n  entity TEXT NOT NULL,\n  entity_ref TEXT,\n  external_id TEXT,\n  status TEXT NOT NULL CHECK (status IN ('ok','pending','skipped','error')),\n  message TEXT,\n  payload TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_square_sync ON square_sync_records(created_at DESC, id DESC);\n\nCREATE TABLE IF NOT EXISTS square_transactions (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  external_id TEXT NOT NULL UNIQUE,\n  kind TEXT NOT NULL,                          -- payment | order | refund | payout\n  source TEXT NOT NULL,                        -- square | local\n  order_code TEXT,\n  square_order_id TEXT,\n  location_id TEXT,\n  amount_cents INTEGER NOT NULL DEFAULT 0,\n  currency TEXT NOT NULL DEFAULT 'AUD',\n  status TEXT,\n  occurred_at TIMESTAMPTZ,\n  raw TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_square_transactions ON square_transactions(occurred_at DESC);\n\n-- ===========================================================================\n-- v3 · WhatsApp Business commerce, centrally managed publishing & inventory,\n--       dine-in settlement, guest feedback → Google reviews, and the Lahore\n--       cultural music system.\n--\n-- Everything here is additive. The order state machine gains metadata columns\n-- (source, payment link, parked) but no new status values, so a database from\n-- an earlier release keeps working untouched.\n-- ===========================================================================\n\n-- Where an order came from, and how it is settled at the table -------------\nALTER TABLE orders ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'web';      -- web | whatsapp | table | pos | counter | phone\nALTER TABLE orders ADD COLUMN IF NOT EXISTS whatsapp_wa_id TEXT;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_link_token TEXT UNIQUE;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_requested_at TIMESTAMPTZ;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS paid_at TIMESTAMPTZ;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS parked BOOLEAN NOT NULL DEFAULT FALSE;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS parked_at TIMESTAMPTZ;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS parked_by TEXT;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS party_size INTEGER NOT NULL DEFAULT 2;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS music_charge_cents INTEGER NOT NULL DEFAULT 0;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS feedback_sent_at TIMESTAMPTZ;\nCREATE INDEX IF NOT EXISTS idx_orders_payment_link ON orders(payment_link_token);\nCREATE INDEX IF NOT EXISTS idx_orders_parked ON orders(parked, channel);\n\n-- Central inventory --------------------------------------------------------\nALTER TABLE menu_items ADD COLUMN IF NOT EXISTS stock_qty INTEGER;                 -- NULL = not counted\nALTER TABLE menu_items ADD COLUMN IF NOT EXISTS track_stock BOOLEAN NOT NULL DEFAULT FALSE;\nALTER TABLE menu_items ADD COLUMN IF NOT EXISTS low_stock_level INTEGER NOT NULL DEFAULT 5;\nALTER TABLE menu_items ADD COLUMN IF NOT EXISTS whatsapp_publish BOOLEAN NOT NULL DEFAULT TRUE;\n\nCREATE TABLE IF NOT EXISTS inventory_movements (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  item_id INTEGER REFERENCES menu_items(id) ON DELETE SET NULL,\n  variant_id INTEGER REFERENCES item_variants(id) ON DELETE SET NULL,\n  delta INTEGER NOT NULL,\n  stock_after INTEGER,\n  reason TEXT NOT NULL,                        -- order | restock | correction | publish\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  actor TEXT NOT NULL DEFAULT 'system',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_inventory_movements ON inventory_movements(item_id, created_at DESC);\n\n-- ===========================================================================\n-- WhatsApp Business\n-- ===========================================================================\n\n-- One row per customer number we have talked to. `state` holds the small\n-- conversation context (nothing sensitive) so a multi-turn order can continue.\nCREATE TABLE IF NOT EXISTS whatsapp_conversations (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  wa_id TEXT NOT NULL UNIQUE,                  -- E.164 digits, no plus\n  display_name TEXT,\n  phone TEXT,\n  state TEXT NOT NULL DEFAULT 'idle',          -- idle | ordering | awaiting_payment\n  context TEXT,                                 -- JSON scratchpad (last items, order code)\n  opt_in BOOLEAN NOT NULL DEFAULT TRUE,\n  order_count INTEGER NOT NULL DEFAULT 0,\n  last_inbound_at TIMESTAMPTZ,\n  last_message_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Every inbound and outbound message, whether it went over the Cloud API or\n-- was mirrored in sandbox mode. This is the WhatsApp audit trail the counter\n-- reads, and the reason a failed send is visible instead of silent.\nCREATE TABLE IF NOT EXISTS whatsapp_messages (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  direction TEXT NOT NULL CHECK (direction IN ('inbound','outbound')),\n  wa_id TEXT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'text',            -- text | cta | template | order | system | catalog | media\n  body TEXT,\n  status TEXT NOT NULL DEFAULT 'logged',        -- sent | delivered | read | failed | logged | received\n  external_id TEXT,\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  conversation_id INTEGER REFERENCES whatsapp_conversations(id) ON DELETE SET NULL,\n  payload TEXT,\n  error TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_whatsapp_messages ON whatsapp_messages(wa_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_whatsapp_messages_order ON whatsapp_messages(order_id, created_at DESC);\n\n-- Central product publishing. One row per menu item per channel, holding the\n-- external catalogue id and the last synchronisation result. WhatsApp is the\n-- first channel; the website and Square reuse the same table and shape.\nCREATE TABLE IF NOT EXISTS channel_publications (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  channel TEXT NOT NULL DEFAULT 'whatsapp' CHECK (channel IN ('whatsapp','website','square')),\n  entity TEXT NOT NULL DEFAULT 'item' CHECK (entity IN ('item','variant','collection')),\n  entity_ref TEXT NOT NULL,\n  external_id TEXT,\n  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','error','removed','skipped')),\n  message TEXT,\n  payload TEXT,\n  published_at TIMESTAMPTZ,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (channel, entity, entity_ref)\n);\nCREATE INDEX IF NOT EXISTS idx_channel_publications ON channel_publications(channel, status);\n\n-- ===========================================================================\n-- Lahore cultural music system\n-- ===========================================================================\nCREATE TABLE IF NOT EXISTS music_tracks (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  title TEXT NOT NULL,\n  artist TEXT,\n  url TEXT NOT NULL,                            -- audio file or YouTube URL (mandatory)\n  provider TEXT NOT NULL DEFAULT 'audio' CHECK (provider IN ('audio','youtube')),\n  kind TEXT NOT NULL DEFAULT 'music' CHECK (kind IN ('music','religious')),\n  category TEXT,                                -- qawwali | naat | hamd | ghazal | punjabi | instrumental | recitation | other\n  duration_seconds INTEGER,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  notes TEXT,\n  created_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_music_tracks_kind ON music_tracks(kind, active);\n\nCREATE TABLE IF NOT EXISTS music_collections (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  slug TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  description TEXT,\n  kind TEXT NOT NULL DEFAULT 'music' CHECK (kind IN ('music','religious')),\n  cover TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS music_collection_tracks (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  collection_id INTEGER NOT NULL REFERENCES music_collections(id) ON DELETE CASCADE,\n  track_id INTEGER NOT NULL REFERENCES music_tracks(id) ON DELETE CASCADE,\n  position INTEGER NOT NULL DEFAULT 0,\n  UNIQUE (collection_id, track_id)\n);\nCREATE INDEX IF NOT EXISTS idx_collection_tracks ON music_collection_tracks(collection_id, position);\n\n-- A collection can be scheduled by weekday and time-of-day. Windows may cross\n-- midnight (22:00 → 02:00); the resolver handles that in lib/music.ts.\nCREATE TABLE IF NOT EXISTS music_schedules (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  collection_id INTEGER NOT NULL REFERENCES music_collections(id) ON DELETE CASCADE,\n  label TEXT,\n  days TEXT,                                     -- CSV 0=Sun..6=Sat, NULL = every day\n  start_time TEXT,                               -- HH:MM (restaurant timezone)\n  end_time TEXT,\n  priority INTEGER NOT NULL DEFAULT 0,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_music_schedules ON music_schedules(active, priority DESC);\n\n-- Singleton row (id = 1) shared by the counter, admin and every open screen.\n-- `mode = auto` follows the schedule; `manual` is a deliberate staff override.\nCREATE TABLE IF NOT EXISTS music_player (\n  id INTEGER PRIMARY KEY,\n  collection_id INTEGER REFERENCES music_collections(id) ON DELETE SET NULL,\n  track_id INTEGER REFERENCES music_tracks(id) ON DELETE SET NULL,\n  status TEXT NOT NULL DEFAULT 'stopped' CHECK (status IN ('playing','paused','stopped')),\n  position_seconds INTEGER NOT NULL DEFAULT 0,\n  volume INTEGER NOT NULL DEFAULT 20,            -- 0-100, deliberately quiet\n  mode TEXT NOT NULL DEFAULT 'auto' CHECK (mode IN ('auto','manual')),\n  encouragement_pending BOOLEAN NOT NULL DEFAULT FALSE,\n  started_at TIMESTAMPTZ,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_by TEXT\n);\n\n-- Customer song requests. The URL is mandatory; staff approve or reject, and\n-- may charge nothing or adjust the pre-ruled amount up or down.\nCREATE TABLE IF NOT EXISTS music_requests (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  token TEXT NOT NULL UNIQUE,\n  customer_name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  table_code TEXT,\n  title TEXT NOT NULL,\n  url TEXT NOT NULL,\n  provider TEXT NOT NULL DEFAULT 'audio' CHECK (provider IN ('audio','youtube')),\n  note TEXT,\n  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','played')),\n  charge_cents INTEGER NOT NULL DEFAULT 0,\n  charge_note TEXT,\n  charge_posted_at TIMESTAMPTZ,\n  reviewed_by TEXT,\n  reviewed_at TIMESTAMPTZ,\n  track_id INTEGER REFERENCES music_tracks(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_music_requests_status ON music_requests(status, created_at DESC);\n\n-- ===========================================================================\n-- Guest feedback → Google review drafts\n-- ===========================================================================\nCREATE TABLE IF NOT EXISTS feedback_invites (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  token TEXT NOT NULL UNIQUE,\n  channel TEXT NOT NULL DEFAULT 'link' CHECK (channel IN ('link','whatsapp','email','qr')),\n  party_size INTEGER NOT NULL DEFAULT 2,\n  sent_at TIMESTAMPTZ,\n  submitted_at TIMESTAMPTZ,\n  rating INTEGER CHECK (rating BETWEEN 1 AND 5),\n  comment TEXT,\n  highlights TEXT,                              -- JSON array of dish names the guest picked\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_feedback_invites_order ON feedback_invites(order_id, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS google_review_drafts (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  feedback_id INTEGER REFERENCES feedback_invites(id) ON DELETE CASCADE,\n  order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,\n  rating INTEGER,\n  body TEXT NOT NULL,\n  image_refs TEXT,                              -- JSON array of dish photo paths\n  bill_cents INTEGER NOT NULL DEFAULT 0,\n  party_size INTEGER NOT NULL DEFAULT 2,\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','skipped')),\n  google_url TEXT,\n  published_at TIMESTAMPTZ,\n  published_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_google_review_drafts ON google_review_drafts(status, created_at DESC);\n";
